const acorn=require('acorn');
const {JSDOM,VirtualConsole}=require('jsdom');

const repo=process.env.GH_REPOSITORY,token=process.env.GH_TOKEN,path='siza-mobile-test/index.html';
const headers={'Accept':'application/vnd.github+json','Authorization':`Bearer ${token}`,'X-GitHub-Api-Version':'2022-11-28'};
const api=`https://api.github.com/repos/${repo}/contents/${path}`;
const assert=(v,m)=>{if(!v)throw new Error(m)};

async function getFile(p){const r=await fetch(`https://api.github.com/repos/${repo}/contents/${p}?ref=main`,{headers});if(!r.ok)throw new Error(`${p}: GET ${r.status}`);const f=await r.json();return{sha:f.sha,text:Buffer.from(f.content.replace(/\n/g,''),'base64').toString('utf8')}}
function parse(html){const so=html.lastIndexOf('<script>'),sc=html.indexOf('</script>',so);assert(so>=0&&sc>so,'main script not found');const start=so+8,code=html.slice(start,sc),ast=acorn.parse(code,{ecmaVersion:'latest'}),decl=[];function walk(n){if(!n||typeof n!=='object')return;if(n.type==='FunctionDeclaration'&&n.id)decl.push(n);for(const[k,v]of Object.entries(n)){if(k==='start'||k==='end')continue;if(Array.isArray(v))v.forEach(walk);else if(v&&typeof v==='object'&&v.type)walk(v)}}walk(ast);return{start,sc,code,decl}}
function replaceFn(html,name,replacement){const p=parse(html),nodes=p.decl.filter(n=>n.id.name===name);assert(nodes.length===1,`${name}: expected 1, got ${nodes.length}`);const n=nodes[0],code=p.code.slice(0,n.start)+replacement+p.code.slice(n.end);return html.slice(0,p.start)+code+html.slice(p.sc)}
function inlineCore(html,files){let out=html;for(const[name,text]of [['card-effects.js',files.effects],['card-schema.js',files.schema],['cards.js',files.cards],['card-renderer.js',files.renderer]]){const tag=`<script src="../siza-core/${name}"></script>`;if(out.includes(tag))out=out.replace(tag,`<script>${text}</script>`)}return out}
function makeDom(html,label){const vc=new VirtualConsole();vc.on('jsdomError',e=>console.error(`[JSDOM ${label}]`,e.message));return new JSDOM(html,{runScripts:'dangerously',url:'https://siza.local/siza-mobile-test/',virtualConsole:vc})}

const usePrism=[
"function manifestBonusSourcesV1(P,c){const spent=new Set(P?.artifactExhausted||[]),out=[];(P?.artifacts||[]).forEach((id,index)=>{if(spent.has(index))return;const source=cardById(id);for(const effect of SizaCardEffects.forEvent(source,'manifest-roll')){if(effect.type!=='manifest-bonus'||!(effect.amount>0))continue;if(effect.requiresPip&&!(c?.pips?.[effect.requiresPip]>0))continue;out.push({index,id,source,effect})}});return out}",
"function applyManifestBonusSourceV1(m,P,bonus){if(!bonus||m.prismBonus)return false;if(bonus.effect.exhaustSource)P.artifactExhausted=[...new Set([...(P.artifactExhausted||[]),bonus.index])];m.prismBonus=bonus.effect.amount;return true}",
"function usePrismV070(){const m=state.modal,P=state.match?.[m?.owner],c=cardById(m?.cardId),bonus=manifestBonusSourcesV1(P,c)[0];if(!m||m.roll==null||m.prismBonus||!bonus)return;if(!applyManifestBonusSourceV1(m,P,bonus))return;addLog('Prisma',bonus.source.name+' se agota: +'+bonus.effect.amount+' visible.');render()}"
].join('\n');

const enemyResolve="function enemyResolveManifestRoll(){const m=state.modal,M=state.match,E=M.enemy,c=cardById(m.cardId);let need=deficitV070(m,E),bonus=manifestBonusSourcesV1(E,c)[0];if(need===1&&bonus){applyManifestBonusSourceV1(m,E,bonus);need=Math.max(0,need-bonus.effect.amount)}const lands=E.hand.map((id,i)=>cardById(id)?.type==='Land'&&i!==m.idx?i:-1).filter(i=>i>=0);if(need<=lands.length)m.burnSelected=lands.slice(0,need);else m.aiFailure=true;save();render()}";

const manifestInline=`function manifestInlineHtml(){
  const m=state.modal,M=state.match;if(!m)return'';const P=M[m.owner],c=cardById(m.cardId),face=m.ai?'':cardThumbHtmlV1(c);
  if(m.stage==='flex')return \`<div class="manifestInlineV5 manifestStageV600"><div class="committedCardV5">\${face}</div><div class="manifestEquationV600"><div class="equationPartsV600">COSTE FLEXIBLE {1}</div><div class="paymentRowV070">\${m.payment.options.map(k=>\`<button class="paymentChoiceV070" onclick="SIZA.choosePaymentV070('\${k}')">\${COLORS[k]}</button>\`).join('')}</div></div></div>\`;
  if(m.stage==='offering')return \`<div class="manifestInlineV5 manifestStageV600"><div class="committedCardV5">\${face}</div><div class="manifestEquationV600"><div class="equationPartsV600">OFRENDA · EN PRUEBA</div><div class="equationTotalV600">Falta <span>\${COLORS[m.payment.missing]}</span></div><div class="paymentRowV070">\${m.payment.candidates.map(x=>\`<button class="offeringChoiceV070" onclick="SIZA.chooseOfferingV070(\${x.index})">\${cardThumbHtmlV1(x.c)}</button>\`).join('')}</div></div></div>\`;
  const rolled=m.roll!=null,lands=P.hand.map((id,i)=>cardById(id)?.type==='Land'&&i!==m.idx?i:-1).filter(i=>i>=0),total=rolled?P.mf+m.roll+m.prismBonus+m.burnSelected.length:0,remain=rolled?Math.max(0,m.dc-total):0,bonusSource=rolled&&!m.prismBonus?manifestBonusSourcesV1(P,c)[0]:null,canFinish=rolled&&remain===0;
  const action=canFinish?\`<button class="collapseSpellV600" onclick="SIZA.commitManifest()">CONTINUAR · ÉXITO</button>\`:rolled&&m.aiFailure?\`<button class="collapseSpellV600" onclick="SIZA.failManifest()">CONTINUAR · FALLO</button>\`:rolled&&!m.ai?\`<button class="collapseSpellV600" onclick="SIZA.failManifest()">ACEPTAR FALLO</button>\`:'';
  return \`<div class="manifestInlineV5 manifestStageV600"><div class="committedCardV5">\${face}</div><div class="mfSourceV600"><div><span>MF</span><b>+\${P.mf}</b></div></div><div class="manifestDieV5 \${rolled?'':'rolling'}">\${rolled?m.roll:'?'}</div><div class="manifestEquationV600"><div class="equationPartsV600">\${rolled?\`MF \${P.mf} + dado \${m.roll}\${m.prismBonus?' + Prisma '+m.prismBonus:''}\${m.burnSelected.length?\` + Burn \${m.burnSelected.length}\`:''}\`: \`Objetivo D\${m.dc}\`}</div><div class="equationTotalV600">\${rolled?\`\${total} <span>/ D\${m.dc}</span>\`:\`D\${m.dc}\`}</div>\${rolled&&remain?\`<div class="equationStatusV600 \${lands.length+(bonusSource?bonusSource.effect.amount:0)>=remain?'wait':'bad'}">FALTAN \${remain}</div>\${bonusSource?\`<button class="paymentChoiceV070" onclick="SIZA.usePrismV070()">AGOTAR PRISMA +\${bonusSource.effect.amount}</button>\`:''}\${!m.ai?\`<div class="burnChoicesV600">\${lands.map(i=>\`<button class="burnChoiceV600 \${m.burnSelected.includes(i)?'selected':''}" onclick="SIZA.selectBurn(\${i})">\${cardThumbHtmlV1(cardById(P.hand[i]))}</button>\`).join('')}</div>\`:''}\`:rolled?'<div class="equationStatusV600 good">ÉXITO</div>':''}\${action}</div></div>\`;
}`;

(async()=>{
 const index=await getFile(path),files={effects:(await getFile('siza-core/card-effects.js')).text,schema:(await getFile('siza-core/card-schema.js')).text,cards:(await getFile('siza-core/cards.js')).text,renderer:(await getFile('siza-core/card-renderer.js')).text};let html=index.text;console.log('Current Mobile blob '+index.sha);
 const marker='window.SIZA={';assert(html.includes(marker),'SIZA export marker missing');
 const oldSource=inlineCore(html,files),oldProbe="window.__PRISM_TEST__={createMatch,setMatch:m=>state.match=m,setModal:m=>state.modal=m,getModal:()=>state.modal,usePrismV070,enemyResolveManifestRoll,manifestInlineHtml,TEST_CARD_DB_V1};\n",oldDom=makeDom(oldSource.replace(marker,oldProbe+marker),'old');oldDom.window.setTimeout=()=>0;
 html=replaceFn(html,'usePrismV070',usePrism);html=replaceFn(html,'enemyResolveManifestRoll',enemyResolve);html=replaceFn(html,'manifestInlineHtml',manifestInline);
 const parsed=parse(html);for(const name of ['usePrismV070','enemyResolveManifestRoll','manifestInlineHtml']){const n=parsed.decl.find(x=>x.id.name===name);assert(n,name+' missing');const src=parsed.code.slice(n.start,n.end);assert(!src.includes("id==='prism'")&&!src.includes("id==='prism'"),name+' still hardcodes prism ID')}
 const newSource=inlineCore(html,files),newProbe="window.__PRISM_TEST__={createMatch,setMatch:m=>state.match=m,setModal:m=>state.modal=m,getModal:()=>state.modal,usePrismV070,enemyResolveManifestRoll,manifestInlineHtml,TEST_CARD_DB_V1,manifestBonusSourcesV1,applyManifestBonusSourceV1};\n",newDom=makeDom(newSource.replace(marker,newProbe+marker),'new');newDom.window.setTimeout=()=>0;
 function setupPlayer(dom,cardId='counter'){const H=dom.window.__PRISM_TEST__,M=H.createMatch(false,'prepare');H.setMatch(M);M.player.artifacts=['prism'];M.player.artifactExhausted=[];M.player.hand=[cardId];const m={type:'manifest',owner:'player',cardId,idx:0,roll:3,burnSelected:[],prismBonus:0,dc:6,ai:false,stage:'roll',payment:{spent:{}}};H.setModal(m);return{H,M,m}}
 const a=setupPlayer(oldDom),b=setupPlayer(newDom);a.H.usePrismV070();b.H.usePrismV070();assert(JSON.stringify({bonus:a.m.prismBonus,spent:a.M.player.artifactExhausted})===JSON.stringify({bonus:b.m.prismBonus,spent:b.M.player.artifactExhausted}),'Player Prism old/new mismatch');console.log('PASS equivalence player Prism activation');
 const aRed=setupPlayer(oldDom,'spark'),bRed=setupPlayer(newDom,'spark');aRed.H.usePrismV070();bRed.H.usePrismV070();assert(aRed.m.prismBonus===0&&bRed.m.prismBonus===0&&aRed.M.player.artifactExhausted.length===0&&bRed.M.player.artifactExhausted.length===0,'Prism incorrectly applies to non-blue card');console.log('PASS equivalence Prism rejects non-blue spell');
 function setupAi(dom){const H=dom.window.__PRISM_TEST__,M=H.createMatch(false,'prepare');H.setMatch(M);M.enemy.artifacts=['prism'];M.enemy.artifactExhausted=[];M.enemy.hand=['counter','dock'];const m={type:'manifest',owner:'enemy',cardId:'counter',idx:0,roll:3,burnSelected:[],prismBonus:0,dc:6,ai:true,stage:'roll',payment:{spent:{}}};H.setModal(m);return{H,M,m}}
 const aiA=setupAi(oldDom),aiB=setupAi(newDom);aiA.H.enemyResolveManifestRoll();aiB.H.enemyResolveManifestRoll();assert(JSON.stringify({bonus:aiA.m.prismBonus,spent:aiA.M.enemy.artifactExhausted,burn:aiA.m.burnSelected})===JSON.stringify({bonus:aiB.m.prismBonus,spent:aiB.M.enemy.artifactExhausted,burn:aiB.m.burnSelected}),'AI Prism old/new mismatch');console.log('PASS equivalence AI Prism activation');
 const H=newDom.window.__PRISM_TEST__;H.TEST_CARD_DB_V1.push({id:'generated_focus',name:'Generated Focus',type:'Artifact',cost:1,difficulty:1,pips:{},text:'Focus.',art:'multi',glyph:'F',effects:[{event:'manifest-roll',type:'manifest-bonus',amount:2,requiresPip:'U',exhaustSource:true}]});let M=H.createMatch(false,'prepare');H.setMatch(M);M.player.artifacts=['generated_focus'];M.player.artifactExhausted=[];M.player.hand=['counter'];const m={type:'manifest',owner:'player',cardId:'counter',idx:0,roll:2,burnSelected:[],prismBonus:0,dc:6,ai:false,stage:'roll',payment:{spent:{}}};H.setModal(m);const source=H.manifestBonusSourcesV1(M.player,cardByIdShim(newDom,'counter'))[0];assert(source?.id==='generated_focus'&&source.effect.amount===2,'Generated manifest bonus source not discovered');H.usePrismV070();assert(m.prismBonus===2&&M.player.artifactExhausted[0]===0,'Generated manifest bonus +2 did not execute');console.log('PASS generated manifest bonus +2');
 const core=newDom.window.SIZA.runArenaCriticalV071();assert(core.passed===core.total,'Arena '+core.passed+'/'+core.total);console.log('PASS Arena '+core.passed+'/'+core.total);oldDom.window.close();newDom.window.close();
 const w=await fetch(api,{method:'PUT',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify({message:'Resolve Prism Manafestation bonus from card data',content:Buffer.from(html,'utf8').toString('base64'),sha:index.sha,branch:'main'})});if(!w.ok)throw new Error(`PUT ${w.status}: ${await w.text()}`);const out=await w.json();console.log('COMMIT '+out.commit.sha);
})().catch(e=>{console.error(e.stack||e.message);process.exit(1)});

function cardByIdShim(dom,id){return dom.window.SizaCardCatalog.get(id)}
